def solve(intervals):
    """Merge overlapping or touching intervals.
    Handles possibly malformed intervals where start may be greater than end by
    normalizing them. Two intervals overlap or touch if the next start is <=
    current end.
    Returns a list of merged intervals sorted by start.
    """
    if not intervals:
        return []
    # Normalize each interval to ensure start <= end
    normalized = []
    for a, b in intervals:
        if a <= b:
            normalized.append([a, b])
        else:
            normalized.append([b, a])
    # Sort by start coordinate
    normalized.sort(key=lambda x: x[0])
    merged = []
    cur_start, cur_end = normalized[0]
    for start, end in normalized[1:]:
        # Overlap or touch when start <= cur_end
        if start <= cur_end:
            cur_end = max(cur_end, end)
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = start, end
    merged.append([cur_start, cur_end])
    return merged
}

def solve(seq):
    """Run-length encode any iterable sequence.
    Returns a list of [element, count] pairs.
    If seq is not iterable or is empty, returns an empty list.
    """
    try:
        items = list(seq)
    except TypeError:
        return []
    if not items:
        return []
    result = []
    current = items[0]
    count = 1
    for elem in items[1:]:
        if elem == current:
            count += 1
        else:
            result.append([current, count])
            current = elem
            count = 1
    result.append([current, count])
    return result

