def solve(seq):
    """Run-length encode any iterable sequence.
    Returns a list of [element, count] pairs.
    If the input is not iterable, returns an empty list.
    """
    try:
        items = list(seq)
    except TypeError:
        return []
    if not items:
        return []
    result = []
    current = items[0]
    count = 1
    for elem in items[1:]:
        if elem == current:
            count += 1
        else:
            result.append([current, count])
            current = elem
            count = 1
    result.append([current, count])
    return result

