def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Non-integer elements are ignored to be robust against malformed input.
    """
    # Filter out non-integer elements; if input is not iterable, treat as empty
    try:
        filtered = [x for x in nums if isinstance(x, int)]
    except Exception:
        return 0
    if not filtered:
        return 0
    import bisect
    tails = []
    for x in filtered:
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)
