def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    Supports '+', '-', '*', '/' with integer division truncating toward zero.
    Tokens may be strings or integers.
    """
    ops = {'+', '-', '*', '/'}
    stack = []
    for t in tokens:
        # Determine if token is an operator
        is_op = isinstance(t, str) and t in ops
        if is_op:
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:  # division trunc toward zero
                # Handle division by zero gracefully (though spec may not require)
                if b == 0:
                    raise ZeroDivisionError('division by zero in RPN')
                stack.append(int(a / b))
        else:
            # Token is a number (string or int)
            if isinstance(t, str):
                stack.append(int(t))
            else:
                stack.append(t)
    return stack[0] if stack else 0

