    ``bytes``/``bytearray`` (decoded as UTF‑8) and gracefully handle ``None``
    or non‑iterable inputs by returning an empty list.
    Returns a list of ``[character, count]`` pairs.
    """
    # Normalise the input to a string sequence of characters
    if s is None:
        return []
    if isinstance(s, (bytes, bytearray)):
        try:
            s = s.decode()
        except Exception:
            s = ''.join(chr(b) for b in s)
    # If it's not a string but is iterable (e.g., list of chars), convert to list
    if not isinstance(s, str):
        try:
            seq = list(s)
        except TypeError:
            return []
    else:
        seq = list(s)
    if not seq:
        return []
    result = []
    cur = seq[0]
    cnt = 1
    for ch in seq[1:]:
        if ch == cur:
